"""Packaged HTML template; no CDN, web server or inference dependencies."""

HTML = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>EgoWorld · 运行检查</title>
<style>
:root{--ink:#192d38;--muted:#5c707a;--line:#dce5e7;--paper:#f3f6f6;--green:#08786e;--amber:#966006;--red:#b53539}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px/1.6 system-ui,-apple-system,"PingFang SC",sans-serif}
button,input,select{font:inherit}button,select{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #08786e;outline-offset:3px}
button{border:1px solid var(--line);border-radius:8px;background:white;color:var(--ink);padding:8px 14px}button:hover{background:#edf5f4}button:disabled{cursor:default;opacity:.45}
.layout{display:grid;grid-template-columns:218px minmax(0,1fr);min-height:100vh}aside{background:#102e37;color:#e2eeef;padding:34px 25px;position:sticky;top:0;height:100vh;display:flex;flex-direction:column}
.brand{font-size:23px;font-weight:750;letter-spacing:-1px}.brand i{display:inline-block;background:#75e3c7;width:11px;height:11px;border-radius:3px;margin-right:9px;transform:rotate(-12deg)}
.eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:1.8px;color:var(--muted);font-weight:700}.aside-sub{color:#a2bdc2;font-size:12px;margin:6px 0 42px}nav a{display:block;text-decoration:none;color:#d6e5e8;border-radius:7px;padding:10px 12px;margin:5px 0}nav a:hover{background:#24434b}nav a:first-child{background:#24434b}.aside-foot{margin-top:auto;color:#a2bdc2;font-size:12px}.aside-foot strong{color:#81dfcb;display:block;margin-bottom:6px}
main{padding:38px 42px 60px;max-width:1600px;width:100%;margin:0 auto}.topline{display:flex;align-items:flex-start;justify-content:space-between;gap:18px}h1{font-size:31px;line-height:1.25;letter-spacing:-1px;margin:9px 0}h2{font-size:18px;margin:0}h3{font-size:15px;margin:0 0 8px}.sub{color:var(--muted);margin:8px 0 0}.mono{font-family:ui-monospace,SFMono-Regular,monospace;font-size:12px;overflow-wrap:anywhere}
.run-name{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.badge{font-size:12px;font-weight:650;border-radius:5px;padding:3px 9px;display:inline-block;background:#e9eef0;color:#49606a;white-space:nowrap}.pass,.passed,.committed{background:#dff3eb;color:#086451}.review,.interrupted,.Retry{background:#fff0d5;color:#805004}.failed,.Failed,.Blocked,.invalid{background:#fce6e7;color:#a12830}.incomplete,.missing{background:#e9eef1;color:#445e70}
.notice{border:1px solid #ead5aa;background:#fff9ec;border-radius:9px;padding:12px 16px;margin-top:22px;color:#715318}.notice strong{font-weight:700}.notice p{margin:3px 0}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px;margin:24px 0}.card{background:white;border:1px solid var(--line);border-radius:11px;padding:20px}.metric{font-size:33px;font-weight:720;line-height:1.2;margin:9px 0 6px;letter-spacing:-1px}.metric small{font-size:15px;font-weight:500;color:var(--muted);letter-spacing:0}.caption{font-size:12px;color:var(--muted)}
.panel{border:1px solid var(--line);background:white;border-radius:11px;margin:20px 0;overflow:hidden;scroll-margin-top:20px}.panel-head{padding:20px 23px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:16px;align-items:center}.panel-head p{margin:3px 0 0;color:var(--muted);font-size:12px}.stage-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(155px,1fr));gap:12px;padding:22px}.stage{border:1px solid var(--line);border-radius:8px;padding:14px;border-top:3px solid #54b7a2}.stage strong{display:block}.stage .caption{min-height:38px;margin-top:5px}.stage .stage-time{font-size:24px;font-weight:650;margin-top:12px}.bar{height:5px;background:#edf2f2;border-radius:4px;margin:8px 0 12px;overflow:hidden}.bar span{display:block;height:100%;background:#138a7b;border-radius:4px}.legend{padding:0 22px 20px;color:var(--muted);font-size:12px}
.toolbar{display:flex;gap:10px;flex-wrap:wrap;padding:17px 22px;border-bottom:1px solid var(--line)}.search{flex:1;min-width:180px}.toolbar input,.toolbar select{border:1px solid #bdcdd1;border-radius:7px;padding:9px 12px;background:white;color:var(--ink)}.table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;text-align:left;white-space:nowrap}th{font-size:11px;letter-spacing:.4px;color:var(--muted);background:#f7f9f9;font-weight:600}td,th{padding:13px 22px;border-bottom:1px solid #edf1f2}td .mono{font-size:12px}td button{padding:4px 10px;font-size:12px}.selected{background:#edf7f4}.empty{text-align:center;color:var(--muted);padding:36px}.pager{display:flex;align-items:center;justify-content:space-between;padding:13px 22px;gap:12px}.pager button{padding:5px 12px}.detail{padding:22px;background:#f9fbfa;border-top:1px solid var(--line)}.detail-top{display:flex;justify-content:space-between;align-items:start;gap:15px}.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-top:16px}.detail ul{padding-left:20px;margin:5px 0}.detail li{overflow-wrap:anywhere}.detail p{margin:5px 0}.error{color:var(--red)}.file{display:flex;justify-content:space-between;gap:15px;border-bottom:1px solid var(--line);padding:6px 0}.detail-stage{margin-bottom:16px}.detail-stage .badge{margin-left:8px}
details{padding:18px 22px}summary{cursor:pointer;font-weight:650}.meta-grid{display:grid;grid-template-columns:150px minmax(0,1fr);gap:10px;margin-top:18px}.meta-grid dt{color:var(--muted)}.meta-grid dd{margin:0}.footer{font-size:12px;color:var(--muted);margin-top:26px}code{overflow-wrap:anywhere}label.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}[hidden]{display:none!important}
@media(max-width:1100px){.layout{grid-template-columns:175px minmax(0,1fr)}aside{padding:28px 17px}main{padding:28px 24px}.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.detail-grid{grid-template-columns:1fr}}
@media(max-width:700px){.layout{display:block}aside{position:static;height:auto;padding:18px 20px}.aside-sub,.aside-foot,nav{display:none}main{padding:24px 15px}.topline{display:block}.topline>button{margin-top:15px}h1{font-size:25px}.cards{gap:10px}.card{padding:15px}.metric{font-size:28px}.panel-head,.toolbar{padding:16px}.stage-grid{padding:16px;grid-template-columns:repeat(2,minmax(0,1fr))}.meta-grid{grid-template-columns:1fr;gap:3px}.meta-grid dd{margin-bottom:12px}td,th{padding:12px 16px}}
@media print{aside,.toolbar,.pager,button{display:none}.layout{display:block}main{padding:0}.panel,.card{break-inside:avoid}.cards{grid-template-columns:repeat(4,1fr)}}
</style></head><body>
<div class="layout"><aside><div class="brand"><i></i>EgoWorld</div><div class="aside-sub">VIDEO → STRUCTURED DATA</div><nav aria-label="报告导航"><a href="#overview">01　运行概览</a><a href="#stages">02　阶段性能</a><a href="#clips">03　片段检查</a><a href="#provenance">04　来源与边界</a></nav><div class="aside-foot"><strong>Offline inspection</strong>运行记录的离线快照<br>无需 GPU · 无外部请求</div></aside>
<main><section id="overview"><div class="topline"><div><div class="eyebrow">Run inspection / 运行检查</div><h1>从运行完成，到结果可信。</h1><div class="run-name"><span class="mono" id="run-id"></span><span id="run-status" class="badge"></span></div></div><button id="download" type="button">导出检查数据 ↓</button></div>
<p class="sub">集中检查执行状态、质量信号与输出完整性；通过 QC 后仍需抽查实际标注。</p>
<div id="warnings" class="notice" hidden></div>
<div class="cards"><div class="card"><div class="eyebrow">已收录片段</div><div class="metric" id="clip-count"></div><div class="caption">报告内已发现的输出 / 日志记录</div></div><div class="card"><div class="eyebrow">优先检查</div><div class="metric" id="attention-count"></div><div class="caption">失败、未完成与 QC 待复核</div></div><div class="card"><div class="eyebrow">QC 通过</div><div class="metric" id="pass-count"></div><div class="caption">自动规则通过，含提交元数据检查</div></div><div class="card"><div class="eyebrow">最近保存的运行耗时</div><div class="metric" id="elapsed"></div><div class="caption">一次调用的墙钟时间，包含冷启动</div></div></div></section>
<section class="panel" id="stages"><div class="panel-head"><div><h2>阶段性能</h2><p>展示最近保存的调用汇总；完整恢复复用的阶段可能没有新计时。</p></div><span class="badge">均值 / 已完成调用</span></div><div id="stage-grid" class="stage-grid"></div><div class="legend">条长按阶段平均墙钟时间比较。各阶段可重叠，时间不能相加当作端到端耗时；墙钟时间包含 CPU 工作与模型加载，不能解释为纯 GPU 时间。</div></section>
<section class="panel" id="clips"><div class="panel-head"><div><h2>片段检查</h2><p>优先排列失败与未完成片段。选择“查看”读取原因、输出行数及提交状态。</p></div><span class="caption" id="clip-scope"></span></div><div class="toolbar"><label class="sr" for="search">搜索视频或片段 ID</label><input class="search" type="search" id="search" placeholder="搜索 video_id / clip_id…"><label class="sr" for="filter">筛选检查状态</label><select id="filter"><option value="all">全部状态</option><option value="attention">优先检查</option><option value="failed">执行失败</option><option value="incomplete">未完成 / 输出不完整</option><option value="review">QC 待复核</option><option value="pass">QC 通过</option><option value="skipped">QC 跳过</option></select></div>
<div class="table-wrap"><table><thead><tr><th>VIDEO / CLIP</th><th>检查状态</th><th>SAM2 帧覆盖率</th><th>对象数</th><th>操作</th></tr></thead><tbody id="clip-rows"></tbody></table></div><div class="pager"><span id="page-info" class="caption" role="status" aria-live="polite"></span><div><button id="prev" type="button" aria-label="上一页">←</button> <button id="next" type="button" aria-label="下一页">→</button></div></div><div id="detail" class="detail" hidden></div></section>
<section class="panel" id="provenance"><details><summary>数据来源与检查边界</summary><dl class="meta-grid" id="meta"></dl><p class="caption">提交检查仅核对运行身份、schema、文件大小与 Parquet 元数据；未重算文件哈希或推理。报告不会读取整份 mask、视频、点云或模型权重，也不判断预测精度。不同模型保留独立坐标系与尺度，尚无统一世界坐标。</p><p class="caption">片段 QC 汇总来自磁盘快照，阶段计时与运行状态来自最近保存的 run_summary.json；它们的统计范围不同。运行中导出可能遇到正在更新的文件，完成后应重新生成。报告包含本地路径和错误信息，分享前请检查。</p></details></section><div class="footer" id="footer"></div>
</main></div>
<script id="report-data" type="application/json">__REPORT_DATA__</script>
<script>
'use strict';
const data=JSON.parse(document.getElementById('report-data').textContent);
const $=id=>document.getElementById(id);
const labels={passed:'执行完成',failed:'执行失败',interrupted:'已中断',pass:'QC 通过',review:'QC 待复核',skipped:'QC 跳过',incomplete:'未完成 / 输出不完整',committed:'提交有效（元数据）',invalid:'提交无效',missing:'无提交',Running:'运行记录',Done:'已完成记录',Failed:'失败记录',Blocked:'上游阻塞',Retry:'重试记录'};
const attention=c=>['failed','incomplete','review'].includes(c.status);
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=String(text);if(cls)n.className=cls;return n;}
function badge(status){return el('span',labels[status]||status,'badge '+(Object.hasOwn(labels,status)?status:''));}
function number(v){return typeof v==='number'&&Number.isFinite(v)?v.toLocaleString('zh-CN'):'—';}
function seconds(v){return typeof v==='number'&&Number.isFinite(v)?v.toFixed(v<10?2:1)+' s':'—';}
function percent(v){return typeof v==='number'&&Number.isFinite(v)?(100*v).toFixed(1)+'%':'—';}
$('run-id').textContent=data.run_id;
const savedStatus=data.summary.status;
$('run-status').replaceWith(Object.assign(badge(savedStatus||'未保存运行汇总'),{id:'run-status'}));
$('clip-count').textContent=number(data.clips.length);
$('attention-count').textContent=number(data.clips.filter(attention).length);
$('pass-count').textContent=number(data.counts.pass||0);
$('elapsed').textContent=seconds(data.summary.elapsed_seconds);
const warnings=[];
if(data.summary.error)warnings.push('最近运行错误：'+data.summary.error);
if(data.truncated)warnings.push(`发现 ${data.discovered_clips} 个片段，仅收录 ${data.clips.length} 个。当前计数与筛选仅覆盖已收录部分；用 --max-clips 提高上限后重新导出。`);
if(data.event_tail_limited)warnings.push('事件记录仅读取末尾 2 MiB；没有输出目录的较早失败片段可能未收录。');
if(!savedStatus)warnings.push('没有已保存的运行汇总；仅展示已有片段与日志证据，无法判断整次运行是否结束。');
if(data.issues.length)warnings.push(...data.issues);
if(warnings.length){$('warnings').hidden=false;$('warnings').append(el('strong','报告范围提示'));warnings.forEach(t=>$('warnings').append(el('p',t)));}
const maxWall=Math.max(0,...data.stages.map(s=>s.wall||0));
for(const stage of data.stages){const card=el('div',undefined,'stage');card.append(el('strong',stage.name),el('div',stage.after.length?'依赖 '+stage.after.join(' + '):'独立分支','caption'),el('div',seconds(stage.wall),'stage-time'));const bar=el('div',undefined,'bar'),fill=el('span');fill.style.width=(maxWall?100*(stage.wall||0)/maxWall:0)+'%';bar.append(fill);card.append(bar,el('div',`${number(stage.calls)} 次完成调用`,'caption'),el('div',`平均排队 ${seconds(stage.queue)}`,'caption'),el('div',`平均写入 ${seconds(stage.write)}`,'caption'),el('div',`模型缓存命中 ${number(stage.cache_hits)}`,'caption'));$('stage-grid').append(card);}
if(!data.stages.length)$('stage-grid').append(el('p','没有启用的模型阶段。','caption'));
let page=0,selected=null,filtered=[];const pageSize=20;
function showDetail(c){selected=c;$('detail').hidden=false;$('detail').replaceChildren();const top=el('div',undefined,'detail-top'),heading=el('div');heading.append(el('h3',c.clip_id),badge(c.status));const close=el('button','关闭');close.type='button';close.onclick=()=>{selected=null;$('detail').hidden=true;renderRows();};top.append(heading,close);$('detail').append(top);
const grid=el('div',undefined,'detail-grid'),left=el('div'),right=el('div');left.append(el('h3','质量与诊断'));
left.append(el('p',`SAM2 空 mask 比例：${percent(c.empty_mask_rate)}`),el('p',`空结果阶段：${c.empty_stages.join(', ')||'—'}`));
if(c.clip.frame_start!==undefined)left.append(el('p',`源帧 [${c.clip.frame_start}, ${c.clip.frame_end}) · ${seconds(c.clip.start_s)} → ${seconds(c.clip.end_s)}`));
const messages=[...c.issues,...Object.entries(c.errors).map(([k,v])=>`${k}: ${v}`)];
if(messages.length){const list=el('ul');messages.forEach(t=>list.append(el('li',t)));left.append(list);}else left.append(el('p','当前自动检查没有列出异常；请继续人工抽查左右手、投影与尺度。','caption'));
right.append(el('h3','阶段提交与文件'));
for(const stage of c.stages){const block=el('div',undefined,'detail-stage'),title=el('strong',stage.name);block.append(title,badge(stage.status));for(const [name,info] of Object.entries(stage.files)){const file=el('div',undefined,'file');file.append(el('span',name,'mono'),el('span',info.rows===undefined?`${number(info.bytes)} bytes`:`${number(info.rows)} 行`,'caption'));block.append(file);}right.append(block);}
if(!c.stages.length)right.append(el('p','无可检查的提交记录。','caption'));
grid.append(left,right);$('detail').append(grid,el('p',c.directory||'未生成片段目录','mono'));renderRows();}
function renderRows(){const body=$('clip-rows');body.replaceChildren();const rows=filtered.slice(page*pageSize,(page+1)*pageSize);for(const c of rows){const tr=el('tr',undefined,selected===c?'selected':''),identity=el('td');identity.append(el('div',c.video_id,'caption'),el('div',c.clip_id,'mono'));const status=el('td');status.append(badge(c.status));const action=el('td'),button=el('button','查看');button.type='button';button.setAttribute('aria-label','查看片段 '+c.clip_id);button.onclick=()=>showDetail(c);action.append(button);tr.append(identity,status,el('td',percent(c.coverage)),el('td',number(c.objects)),action);body.append(tr);}if(!rows.length){const td=el('td','没有匹配的片段。','empty');td.colSpan=5;const tr=el('tr');tr.append(td);body.append(tr);}
$('page-info').textContent=filtered.length?`${page*pageSize+1}–${Math.min((page+1)*pageSize,filtered.length)} / ${filtered.length} 个片段`:'0 个片段';$('prev').disabled=page===0;$('next').disabled=(page+1)*pageSize>=filtered.length;}
function filter(){const q=$('search').value.trim().toLowerCase(),state=$('filter').value;filtered=data.clips.filter(c=>(c.video_id+' '+c.clip_id).toLowerCase().includes(q)&&(state==='all'||(state==='attention'?attention(c):c.status===state)));page=0;selected=null;$('detail').hidden=true;renderRows();}
$('search').addEventListener('input',filter);$('filter').addEventListener('change',filter);$('prev').onclick=()=>{page--;renderRows();};$('next').onclick=()=>{page++;renderRows();};filter();
$('clip-scope').textContent=data.truncated?'部分片段':'已发现的片段';
for(const [label,value] of [['运行目录',data.run_dir],['导出时间',new Date(data.generated_at).toLocaleString()+'（本机时区）'],['输出 schema',data.schema_version],['运行指纹',data.fingerprint||'未记录'],['完整性检查','提交元数据；未重算 SHA-256'],['SAM2 帧覆盖率','已处理帧 / 片段预期帧；不代表每帧都有目标'],['不同坐标系','HaMeR: hand_root / model_prior；FP: object_to_camera / meters；Fast3R: first_view_world / 以产物 scale_status 为准']]){$('meta').append(el('dt',label),el('dd',value,'mono'));}
$('footer').textContent=`EgoWorld · schema ${data.schema_version} · 离线快照，不自动刷新。重新执行 egoworld report 可更新报告。`;
$('download').onclick=()=>{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download='egoworld-inspection.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);};
</script></body></html>'''
